203		}
204	
205		// 用一个真实打开在完好文件上的句柄，随后在句柄之外把文件改坏，
206		// 验证每条操作路径都以同一份损坏判定拒绝。
207		recoverPath := filepath.Join(t.TempDir(), "recover.json")
208		if err := os.WriteFile(recoverPath, good, 0o600); err != nil {
209			t.Fatal(err)
210		}
211		h, err := Open(recoverPath)
212		if err != nil {
213			t.Fatal(err)
214		}
215		defer h.Close()
216		if err := os.WriteFile(recoverPath, bad, 0o600); err != nil {
217			t.Fatal(err)
218		}
219		checks := map[string]func() error{
220			"VoteProposal":      func() error { _, _, e := h.VoteProposal("gip-bal"); return e },
221			"VoteProposals":     func() error { _, e := h.VoteProposals(); return e },
222			"ProposalsSnapshot": func() error { _, e := h.ProposalsSnapshot(); return e },
223			"Proposal":          func() error { _, _, e := h.Proposal("gip-bal"); return e },
224			"Proposals":         func() error { _, e := h.Proposals(); return e },
225			"Receipt":           func() error { _, _, e := h.Receipt("gip-bal"); return e },
226			"Receipts":          func() error { _, e := h.Receipts(); return e },
227			"Balance":           func() error { _, e := h.Balance("audits"); return e },
228			"Balances":          func() error { _, e := h.Balances(); return e },
229			"BalanceSnapshot":   func() error { _, e := h.BalanceSnapshot(); return e },
230			"TreasuryBalance":   func() error { _, e := h.TreasuryBalance(); return e },
231			// 已投过票的 alice 在缺损文件上绝不能被当成“尚未投票”而再次投出。
232			"CastVote": func() error { _, e := h.CastVote("gip-bal", "alice", true, 100); return e },
233			// 到期计票绝不能按零参与权重给出拒绝结论。
234			"TallyVote": func() error { _, e := h.TallyVote("gip-bal", 200); return e },
235			// 即使文件被改成 passed 类缺损，执行也不能继续转账（本变体为 voting，
236			// 这里同样断言损坏判定先于状态判断）。
237			"Execute": func() error { _, e := h.Execute("gip-bal", 300); return e },
238		}
239		for name, op := range checks {
240			if e := op(); !errors.Is(e, ErrStateCorrupt) {
241				t.Fatalf("%s after corruption err=%v, want ErrStateCorrupt", name, e)
242			}
243		}
244		if got, rerr := os.ReadFile(recoverPath); rerr != nil || string(got) != string(bad) {
245			t.Fatalf("failed ops rewrote or normalized the state file")
246		}
247	}
248	
249	// TestCorruptBallotsCLIUsesSameJudgement：命令行普通输出与 --json 使用同
250	// 一份判定：失败时不向标准输出给出成功记录或部分结果，原因写入标准错误，
251	// 退出码为 1。
252	func TestCorruptBallotsCLIUsesSameJudgement(t *testing.T) {
253		binary := buildCLI(t)
254		path, _, _ := corruptBallotsState(t, "voting", func(p map[string]any) {
255			p["ballots"] = nil
256		})
257		commands := [][]string{
258			{"proposal", "--id", "gip-bal"},
259			{"proposals"},
260			{"vote", "--id", "gip-bal", "--voter", "alice", "--choice", "for", "--now", "100"},
261			{"tally", "--id", "gip-bal", "--now", "200"},
262			{"execute", "--id", "gip-bal", "--now", "300"},
263			{"balances"},
264			{"receipts"},
265		}
266		for _, args := range commands {
267			for _, asJSON := range []bool{false, true} {
268				name := strings.Join(args, " ")
269				full := args
270				if asJSON {
271					full = append(append([]string{}, full...), "--json")
272					name += " --json"
273				}
274				so, se, code := runCLI(t, binary, path, full...)
275				if code != 1 {
276					t.Fatalf("%s: exit code=%d, want 1; stdout=%s stderr=%s", name, code, so, se)
277				}
278				if so != "" {
279					t.Fatalf("%s: stdout must stay empty, got: %s", name, so)
280				}
281				if !strings.Contains(se, "corrupt") || !strings.Contains(se, "gip-bal") ||
282					!strings.Contains(se, "ballots") {
283					t.Fatalf("%s: stderr must name corrupt state, proposal and ballots, got: %s", name, se)
284				}
285			}
286		}
287	}
288	
289	// TestCorruptBallotsSiblingProposalRejectsWholeFile：文件里即使还有另一项
290	// 内容完整的提案，也不能只略过坏提案继续查询或投票——整份文件判损坏。
291	func TestCorruptBallotsSiblingProposalRejectsWholeFile(t *testing.T) {
292		path, good, bad := corruptBallotsState(t, "voting", func(p map[string]any) {
293			delete(p, "ballots")
294		})
295		var doc map[string]any
296		if err := json.Unmarshal(bad, &doc); err != nil {
297			t.Fatal(err)
298		}
299		props := doc["vote_proposals"].(map[string]any)
300		props["gip-ok"] = map[string]any{
301			"id": "gip-ok", "state": "voting",
302			"members":     []any{map[string]any{"id": "zoe", "weight": 1}},
303			"delegations": []any{},
304			"quorum":      1, "start_at": 0, "deadline": 200, "timelock_end": 300,
305			"actions": []any{}, "ballots": []any{},
306		}
307		withSibling, err := json.MarshalIndent(doc, "", "  ")
308		if err != nil {
309			t.Fatal(err)
310		}
311		withSibling = append(withSibling, '\n')
312		if err := os.WriteFile(path, withSibling, 0o600); err != nil {
313			t.Fatal(err)
314		}
315		s, err := Open(path)
316		if !errors.Is(err, ErrStateCorrupt) || s != nil {
317			if s != nil {
318				s.Close()
319			}
320			t.Fatalf("Open with sibling good proposal: store=%v err=%v", s, err)
321		}
322		if !strings.Contains(err.Error(), `"gip-bal"`) || !strings.Contains(err.Error(), "ballots") {
323			t.Fatalf("error must still name the corrupt proposal, got: %v", err)
324		}
325	
326		// 句柄打开在完好文件上，随后在文件内加入坏提案：即使查询/投票目标是
327		// 完好的 gip-ok，也不得返回部分列表或写入新票。
328		livePath := filepath.Join(t.TempDir(), "live.json")
329		if err := os.WriteFile(livePath, good, 0o600); err != nil {
330			t.Fatal(err)
331		}
332		live, err := Open(livePath)
333		if err != nil {
334			t.Fatal(err)
335		}
336		defer live.Close()
337		if err := os.WriteFile(livePath, withSibling, 0o600); err != nil {
338			t.Fatal(err)
339		}
340		if _, ok, qerr := live.VoteProposal("gip-ok"); !errors.Is(qerr, ErrStateCorrupt) {
341			t.Fatalf("querying the intact sibling must still fail: ok=%v err=%v", ok, qerr)
342		}
343		if _, qerr := live.VoteProposals(); !errors.Is(qerr, ErrStateCorrupt) {
344			t.Fatalf("listing proposals must not skip the bad one: err=%v", qerr)
345		}
346		if _, verr := live.CastVote("gip-ok", "zoe", true, 100); !errors.Is(verr, ErrStateCorrupt) {
347			t.Fatalf("voting on the intact sibling must still fail: err=%v", verr)
348		}
349		if got, rerr := os.ReadFile(livePath); rerr != nil || string(got) != string(withSibling) {
350			t.Fatalf("failed ops rewrote or normalized the state file")
351		}
352	}
353	
354	// TestExplicitEmptyBallotsLegal：明确写出的空数组仍表示确实无人投票。
355	// 正常创建提案后应可直接查询并在窗口内接受首次投票；无人投票时到期计票
356	// 得到赞成、反对与参与权重均为零的拒绝结论，该记录之后仍可正常查询。
357	func TestExplicitEmptyBallotsLegal(t *testing.T) {
358		t.Run("handwritten empty array accepts first vote", func(t *testing.T) {
359			dir := t.TempDir()
360			path := filepath.Join(dir, "treasury.json")
361			raw := `{
362	  "magic": "govflow-treasury-state",
363	  "version": 1,
364	  "initial_treasury": 1000,
365	  "treasury": 1000,
366	  "balances": {},
367	  "proposals": {},
368	  "receipts": [],
369	  "vote_proposals": {
370	    "gip-empty": {
371	      "id": "gip-empty",
372	      "state": "voting",
373	      "members": [{"id": "alice", "weight": 300}, {"id": "bob", "weight": 200}],
374	      "delegations": [],
375	      "quorum": 250,
376	      "start_at": 0,
377	      "deadline": 200,
378	      "timelock_end": 300,
379	      "actions": [],
380	      "ballots": []
381	    }
382	  }
383	}
384	`
385			if err := os.WriteFile(path, []byte(raw), 0o600); err != nil {
386				t.Fatal(err)
387			}
388			store, err := Open(path)
389			if err != nil {
390				t.Fatalf("empty ballots array rejected: %v", err)
391			}
392			defer store.Close()
393			v, ok, err := store.VoteProposal("gip-empty")
394			if err != nil || !ok || len(v.Ballots) != 0 {
395				t.Fatalf("query empty ballots: ok=%v ballots=%+v err=%v", ok, v, err)
396			}
397			// 窗口内的首次投票必须被接受。
398			b, err := store.CastVote("gip-empty", "bob", false, 100)
399			if err != nil || b.Representative != "bob" || b.Weight != 200 || b.Support || b.VotedAt != 100 {
400				t.Fatalf("first vote into empty list: %+v err=%v", b, err)
401			}
402			store.Close()
403			reopened, err := Open(path)
404			if err != nil {
405				t.Fatalf("reopen after first vote: %v", err)
406			}
407			defer reopened.Close()
408			rv, ok, err := reopened.VoteProposal("gip-empty")
409			if err != nil || !ok || len(rv.Ballots) != 1 {
410				t.Fatalf("reopen query: %+v ok=%v err=%v", rv, ok, err)
411			}
412			got := rv.Ballots[0]
413			if got.Representative != "bob" || got.Weight != 200 || got.Support || got.VotedAt != 100 {
414				t.Fatalf("first ballot must keep order, representative, weight, choice and first time: %+v", got)
415			}
416			// 相同选择重试返回首次记录；改投报冲突，既有规则不因空数组来源放宽。
417			if retry, rerr := reopened.CastVote("gip-empty", "bob", false, 150); rerr != nil ||
418				retry.VotedAt != 100 {
419				t.Fatalf("same-choice retry must return first record: %+v err=%v", retry, rerr)
420			}
421			if _, rerr := reopened.CastVote("gip-empty", "bob", true, 100); !errors.Is(rerr, ErrProposalConflict) {
422				t.Fatalf("changing choice must conflict, got %v", rerr)
423			}
424		})
425	
426		t.Run("create then zero-turnout tally still queryable", func(t *testing.T) {
427			// 从不含整张投票提案表的旧版状态文件起步：旧文件仍可读。
428			dir := t.TempDir()
429			path := filepath.Join(dir, "treasury.json")
430			old := `{
431	  "magic": "govflow-treasury-state",
432	  "version": 1,
433	  "initial_treasury": 1000,
434	  "treasury": 1000,
435	  "balances": {},
436	  "proposals": {},
437	  "receipts": []
438	}
439	`
440			if err := os.WriteFile(path, []byte(old), 0o600); err != nil {
441				t.Fatal(err)
442			}
443			store, err := Open(path)
444			if err != nil {
445				t.Fatalf("old state file rejected: %v", err)
446			}
447			in := &CreateVoteInput{
448				ID:       "gip-novote",
449				Members:  []VoteMember{{ID: "alice", Weight: 300}, {ID: "bob", Weight: 200}},
450				Quorum:   250,
451				StartAt:  0,
452				Deadline: 200, TimelockEnd: 300,
453				Actions: []string{},
454			}
455			if v, existed, err := store.CreateVoteProposal(in); err != nil || existed || (v != nil && len(v.Ballots) != 0) {
456				t.Fatalf("create: existed=%v err=%v view=%+v", existed, err, v)
457			}
458			store.Close()
459	
460			// 落盘记录必须明确写出空数组，而不是省略 ballots。
461			persisted, err := os.ReadFile(path)
462			if err != nil {
463				t.Fatal(err)
464			}
465			if !strings.Contains(string(persisted), `"ballots": []`) {
466				t.Fatalf("persisted state must write explicit empty ballots array:\n%s", persisted)
467			}
468			reopened, err := Open(path)
469			if err != nil {
470				t.Fatalf("reopen after create: %v", err)
471			}
472			defer reopened.Close()
473			// 无人投票到期计票：赞成、反对、参与权重均为零的拒绝结论。
474			res, err := reopened.TallyVote("gip-novote", 200)
475			if err != nil {
476				t.Fatalf("zero-turnout tally: %v", err)
477			}
478			if res.Passed || res.ForWeight != 0 || res.AgainstWeight != 0 || res.Turnout != 0 {
479				t.Fatalf("zero-turnout tally = %+v, want rejected with all-zero weights", res)
480			}
481			// 拒绝后记录仍可正常查询，结论与首次计票一致。
482			v, ok, err := reopened.VoteProposal("gip-novote")
483			if err != nil || !ok || v.State != "rejected" || len(v.Ballots) != 0 {
484				t.Fatalf("query after zero tally: %+v ok=%v err=%v", v, ok, err)
485			}
486			if v.Tally == nil || v.Tally.ForWeight != 0 || v.Tally.AgainstWeight != 0 ||
487				v.Tally.Turnout != 0 || v.Tally.Passed {
488				t.Fatalf("tally view after zero-turnout rejection: %+v", v.Tally)
489			}
490			reopened.Close()
491			if s, err := Open(path); err != nil || s == nil {
492				if s != nil {
493					s.Close()
494				}
495				t.Fatalf("rejected zero-turnout record must stay readable: %v", err)
496			} else {
497				s.Close()
498			}
499		})
500	}
