	reopened, err := Open(path)
	if err != nil {
		t.Fatalf("Open legacy file: %v", err)
	}
	if bal, err := reopened.TreasuryBalance(); err != nil || bal != 500 {
		t.Fatalf("TreasuryBalance=%d err=%v", bal, err)
	}
	reopened.Close()

	// 同一文件再缺 treasury：仍必须拒绝。
