package main

import (
	"fmt"
	"os"

	gov "github.com/gzhysuiioo/govflow-proposals/govflow"
)

func main() {
	path := "/tmp/satcheck/state.json"
	if _, err := gov.InitTreasury(path, 100); err != nil { panic(err) }
	s, err := gov.Open(path)
	if err != nil { panic(err) }
	_, _, err = s.CreateVoteProposal(&gov.CreateVoteInput{
		ID: "g1", Members: []gov.VoteMember{{ID: "a", Weight: 1}},
		Quorum: 1, StartAt: 0, Deadline: 10, TimelockEnd: 10,
	})
	if err != nil { panic(err) }
	s.Close()
	raw, _ := os.ReadFile(path)
	out := string(raw)
	out = replaceOnce(out, `"start_at": 0`, `"start_at": -1`)
	if err := os.WriteFile(path, []byte(out), 0o600); err != nil { panic(err) }
	s2, err := gov.Open(path)
	fmt.Printf("open err = %v\nis corrupt = %v\nstore nil = %v\n", err, errorIs(err, gov.ErrStateCorrupt), s2 == nil)
}

func replaceOnce(s, old, new string) string {
	for i := 0; i+len(old) <= len(s); i++ {
		if s[i:i+len(old)] == old { return s[:i] + new + s[i+len(old):] }
	}
	return s
}
func errorIs(err, target error) bool {
	if err == nil { return false }
	type iser interface{ Is(error) bool }
	for err != nil {
		if err == target { return true }
		if u, ok := err.(interface{ Unwrap() error }); ok { err = u.Unwrap(); continue }
		break
	}
	_ = iser(nil)
	return false
}
EOF
